const categoryMessage=(error:any)=>{
 const code=error?.code||error?.message;
 if(code==='CATEGORY_INPUT')return 'راجع اسم التصنيف والوصف.';
 if(code==='CATEGORY_MANAGERS_REQUIRED')return 'أسند التصنيف إلى مدير واحد على الأقل.';
 if(code==='CATEGORY_MANAGER_INVALID')return 'يوجد مدير غير متاح للإسناد.';
 if(code==='CATEGORY_PRINCIPAL_ASSIGNMENT_REQUIRED')return 'يجب إبقاء المدير الرئيسي ضمن إسنادات هذا التصنيف.';
 if(code==='CATEGORY_NAME_CONFLICT'||code==='ER_DUP_ENTRY')return 'اسم التصنيف مستخدم لدى أحد المدراء المحددين.';
 if(code==='CATEGORY_HAS_MEMBERS')return 'لا يمكن إزالة هذا المدير ما دام للتصنيف مشتركون تابعون له.';
 if(code==='CATEGORY_NOT_FOUND'||code==='CATEGORY_BULK_NOT_FOUND')return 'يوجد تصنيف غير متاح أو لا تملك صلاحية إدارته.';
 if(code==='CATEGORY_BULK_INPUT')return 'حدد تصنيفًا واحدًا على الأقل لتنفيذ العملية.';
 if(code==='NETWORK_AUTH')return 'لا تملك صلاحية تنفيذ هذه العملية.';
 return 'تعذر حفظ التصنيف.';
};
router.get('/:slug/categories',async(req,res)=>{try{return res.json(await networkCategories(await categoryScope(req)));}catch(e){return res.status(403).json({message:categoryMessage(e)});}});
const subscriberMessage=(e:any)=>{
 const code=e?.message||e?.code;
 if(['ER_NO_SUCH_TABLE','ER_BAD_FIELD_ERROR'].includes(e?.code))return 'تحتاج قاعدة هذه الشبكة إلى تطبيق ترقية تخزين بيانات الهوية من tenant-upgrades قبل المتابعة.';
 if(code==='NETWORK_AUTH')return 'انتهت الجلسة أو لا تملك صلاحية إدارة المشتركين.';
 if(code==='SUBSCRIBER_INPUT')return 'راجع البيانات المدخلة.';
 if(code==='SUBSCRIBER_CATEGORY_UNAVAILABLE')return 'التصنيف غير مسند إلى مدير المشترك.';
 if(code==='SUBSCRIBER_NOT_FOUND')return 'المشترك غير موجود أو لا تملك صلاحية الوصول إليه.';
 if(code==='SUBSCRIBER_NATIONAL_NUMBER_EXISTS')return 'الرقم الوطني مسجل مسبقًا على ملف مشترك آخر.';
 if(code==='SUBSCRIBER_NATIONAL_NUMBER_INVALID')return 'الرقم الوطني السوري يجب أن يتكوّن من 11 رقمًا. أعد قراءة الهوية وتحقق من الرقم.';
 if(code==='SUBSCRIBER_PHONE_EXISTS')return 'رقم الهاتف مسجل مسبقًا على ملف مشترك آخر.';
 if(e?.code==='ER_DUP_ENTRY')return 'الرقم الوطني مسجل مسبقًا على ملف مشترك آخر.';
 return 'تعذر حفظ بيانات المشترك.';
};
const subscriberCardTemplateError=(error:unknown,operation:'read'|'save')=>{
 const value=error as {message?:string;code?:string};
 const code=value?.code||value?.message||'SUBSCRIBER_CARD_TEMPLATE_FAILED';
 console.error('[subscriber-card-template]',{operation,code});
 if(code==='ER_NO_SUCH_TABLE')return {status:503,message:'قاعدة بيانات هذه الشبكة تفتقد جدول قالب بطاقة المشترك. طبّق ترقية 20261026_subscriber_card_templates.sql على قاعدة rl_tenant الخاصة بها، ثم أعد المحاولة.'};
 if(code==='ER_NO_REFERENCED_ROW_2'||code==='ER_NO_REFERENCED_ROW')return {status:409,message:'تعذر اعتماد القالب بسبب عدم تطابق حساب المدير مع قاعدة بيانات الشبكة. أعد تسجيل الدخول ثم حاول الحفظ.'};
 return {status:503,message:operation==='read'?'تعذر تحميل قالب بطاقة المشترك. راجع سجل الباك إند لمعرفة سبب قاعدة البيانات.':'تعذر حفظ قالب بطاقة المشترك. راجع سجل الباك إند لمعرفة سبب قاعدة البيانات.'};
};
router.get('/:slug/subscriber-card-template',async(req,res)=>{try{return res.json(await readSubscriberCardTemplate(await categoryScope(req)));}catch(e){const code=(e as Error).message;if(code==='NETWORK_AUTH')return res.status(401).json({message:'لا تملك صلاحية عرض قالب بطاقة المشترك.'});const failure=subscriberCardTemplateError(e,'read');return res.status(failure.status).json({message:failure.message});}});
router.put('/:slug/subscriber-card-template',async(req,res)=>{try{return res.json(await saveSubscriberCardTemplate(await principal(req),req.body));}catch(e){const code=(e as Error).message;if(code==='NETWORK_AUTH')return res.status(401).json({message:'لا تملك صلاحية اعتماد قالب بطاقة المشترك.'});if(code==='SUBSCRIBER_CARD_INPUT')return res.status(422).json({message:'تحقق من خيارات تصميم البطاقة.'});const failure=subscriberCardTemplateError(e,'save');return res.status(failure.status).json({message:failure.message});}});
