const nasError=(e:unknown)=>({message:(e as Error)?.message==='NAS_PLAN_LIMIT_REACHED'?'وصلت إلى عدد أجهزة NAS المسموح به في الخطة.':(e as Error)?.message==='NAS_INPUT_INVALID'?'تحقق من البيانات الأساسية وخدمات RADIUS.':(e as Error)?.message==='NAS_OVPN_SERVER_ADDRESS_INVALID'?'عنوان طرف خادم OVPN المحفوظ غير صالح؛ راجع إعداد النفق.':(e as Error)?.message==='NAS_API_ROUTE_UNAVAILABLE'?'لا يملك خادم التطبيق مسارًا صالحًا إلى عنوان نفق NAS. تحقق من مسار IP بين خادم التطبيق والبوابة ثم أعد عرض السكربت.':(e as Error)?.message==='RADIUS_OVPN_ROUTE_CONFLICT'?'نطاق نفق OVPN يتداخل مع مسار آخر أو مع بوابة مختلفة على خادم RADIUS. خصص نطاقًا فريدًا لكل بوابة.':(e as Error)?.message==='RADIUS_OVPN_ROUTE_SYNC_FAILED'?'تعذر تثبيت مسارات OVPN الدائمة على Ubuntu عبر SSH. تحقق من القفزة المباشرة واتصال SSH ثم أعد المحاولة.':(e as Error)?.message==='NAS_STATUS_INPUT'?'حالة NAS المحددة غير صالحة.':(e as Error)?.message==='NAS_DETAILS_INPUT'?'تحقق من اسم NAS وأطوال الحقول ثم أعد الحفظ.':(e as Error)?.message==='NAS_NOT_FOUND'?'جهاز NAS غير موجود أو مؤرشف.':(e as Error)?.message==='NETWORK_AUTH'?'انتهت الجلسة أو لا تملك صلاحية إدارة الخوادم.':'تعذر تجهيز اتصال NAS. يمكنك إعادة المحاولة لاستكماله؛ راجع البوابة والشهادات وSSH.',code:/^[A-Z0-9_]+$/.test((e as Error)?.message??'')?(e as Error).message:'NAS_OPERATION_FAILED'});
async function syncNasRadius(central:any,app:any,scope:any,snapshot:any){
 const state=await readPrivateSetting('environment_runtime','environment_'+scope.environment_id);if(!state||state.tenantId!==Number(scope.tenant_id)||state.subscriptionId!==Number(scope.subscription_id)||state.radiusServerId!==snapshot.radiusServerId)throw new Error('NAS_RADIUS_SCOPE');
 const [configs]:any=await central.query("SELECT setting_value FROM platform_settings WHERE id=? AND setting_group='free_radius'",[snapshot.radiusServerId]);if(!configs[0])throw new Error('RADIUS_NOT_FOUND');const radius=JSON.parse(configs[0].setting_value);
 const [servers]:any=await central.query('SELECT * FROM database_servers WHERE id=?',[scope.database_server_id]);if(!servers[0]||servers[0].tls_required||Number(radius.sshServerId)!==Number(state.radiusSshServerId))throw new Error('NAS_RADIUS_SCOPE');
 await syncRadiusOvpnRoutes(central,Number(radius.sshServerId),Number(scope.environment_id));
 await applyRadiusDatabase({sshServerId:radius.sshServerId,radiusHost:radius.host,databaseHost:await radiusDatabaseHost(servers[0],radius.host),databasePort:Number(servers[0].port),databaseName:scope.db_name,username:scope.radius_username,password:decryptProvisioningSecret(scope.radius_password_encrypted),authPort:state.authPort,accountingPort:state.accountingPort,name:'rl_env_'+scope.environment_id,secret:decryptProvisioningSecret(state.radiusSecretEncrypted),clients:await nasRadiusClients(app)});
 await markNasRadiusConfigured(app);
}
router.get('/:slug/dashboard',async(req,res)=>{
 try{const scope=await principal(req);const tab=String(req.query.tab||'overview');
 const queries:Record<string,string>={
  subscribers:"SELECT p.id,CONCAT(c.first_name,' ',c.last_name) name,r.current_username username,p.admin_status status,p.line_name lineName FROM pppoe_accounts p JOIN customers c ON c.id=p.customer_id JOIN radius_identities r ON r.id=p.radius_identity_id WHERE p.archived_at IS NULL ORDER BY p.id DESC LIMIT 200",
  profiles:"SELECT id,name,package_type type,is_enabled enabled,base_price price,currency_code currency FROM pppoe_packages WHERE archived_at IS NULL ORDER BY id DESC LIMIT 200",
  hotspot:"SELECT h.id,r.current_username username,h.account_kind type,h.status,h.login_mode loginMode FROM hotspot_accounts h JOIN radius_identities r ON r.id=h.radius_identity_id WHERE h.archived_at IS NULL ORDER BY h.id DESC LIMIT 200",
  settings:"SELECT network_name networkName,description,timezone,primary_contact_phone phone,radius_interim_update_seconds interimUpdate,grace_policy gracePolicy,global_grace_days graceDays FROM network_settings WHERE id=1"
 };
 if(tab!=='overview'&&!queries[tab])return res.status(400).json({message:'القسم غير صالح.'});
 const data=await withNetwork(scope,async app=>{if(tab==='overview')return readNetworkDashboardOverview(app);const [items]=await app.query(queries[tab]);return {items};});return res.json(data);
 }catch(e){if((e as Error).message==='NETWORK_AUTH'||(e as Error).name==='TokenExpiredError'||(e as Error).name==='JsonWebTokenError')return res.status(401).json({message:'انتهت الجلسة أو لا تملك صلاحية إدارة الشبكة.'});console.error(e);return res.status(503).json({message:'تعذر تحميل بيانات الشبكة.'});}
});
router.get('/:slug/nas',async(req,res)=>{try{const scope=await principal(req);return res.json(await withNetwork(scope,async app=>{const snapshot=await readNetworkOvpn(app);const [timezoneRows]:any=await app.query('SELECT timezone FROM network_settings WHERE id=1');const networkTimezone=String(timezoneRows[0]?.timezone||'Asia/Damascus');const [rows]:any=await app.query("SELECT l.id,l.name,l.vendor,l.model,l.routeros_version,l.radius_services,l.is_enabled,l.location,l.description,l.activity_status,l.last_seen_at,c.tunnel_address,c.server_host,c.central_tunnel_id,c.configuration_snapshot,JSON_EXTRACT(c.configuration_snapshot,'$.radiusConfigured') radius_ready,ms.port api_port,ms.is_enabled api_enabled,(SELECT COUNT(DISTINCT ra.username) FROM radacct ra WHERE ra.nasipaddress=c.tunnel_address AND ra.acctstoptime IS NULL AND COALESCE(ra.acctupdatetime,ra.acctstarttime)>=UTC_TIMESTAMP(6)-INTERVAL 6 MINUTE) connected_accounts FROM lord_nas l LEFT JOIN nas_ovpn_connections c ON c.nas_id=l.id LEFT JOIN nas_management_services ms ON ms.lord_nas_id=l.id AND ms.service_type='api' WHERE l.archived_at IS NULL ORDER BY l.id");return {timezone:networkTimezone,configured:Boolean(snapshot),maxNas:snapshot?snapshot.maxNas===0?0:snapshot.maxNas+snapshot.additionalNas:0,items:rows.map((r:any)=>{let config:any={};try{config=typeof r.configuration_snapshot==='string'?JSON.parse(r.configuration_snapshot):r.configuration_snapshot||{};}catch{}const samples=Array.isArray(config.telemetrySamples)?config.telemetrySamples.slice(-36):[];return {id:Number(r.id),name:r.name,vendor:r.vendor,model:r.model??null,routerosVersion:r.routeros_version??config.telemetryLatest?.version??null,boardName:config.telemetryLatest?.board??null,uptime:config.telemetryLatest?.uptime??null,services:String(r.radius_services||'').split(',').filter(Boolean),isEnabled:Number(r.is_enabled)===1,address:r.tunnel_address??null,apiPort:r.api_port?Number(r.api_port):null,apiEnabled:Number(r.api_enabled)===1,apiLastCheck:config.apiLastCheck??null,location:r.location??null,description:r.description??null,radiusConfigured:String(r.radius_ready)==='true',ready:Boolean(r.central_tunnel_id)&&String(r.radius_ready)==='true',metrics:samples,metricsUpdatedAt:config.telemetryLatest?.receivedAt??null,connectedAccounts:Number(r.connected_accounts||0),status:r.activity_status==='recent'&&r.last_seen_at&&Date.now()-new Date(r.last_seen_at).getTime()<90000?'connected':r.activity_status==='stale'?'disconnected':'awaiting_link',lastSeenAt:r.last_seen_at};})};}));}catch{return res.status(401).json({message:'انتهت الجلسة أو لا تملك صلاحية إدارة الخوادم.'});}});
router.post('/:slug/nas/:id/telemetry',async(req,res)=>{
 try{
  const id=Number(req.params.id),provided=String(req.get('authorization')||'').replace(/^Bearer\s+/i,'');if(!Number.isSafeInteger(id)||id<1||!/^[-_A-Za-z0-9]{40,50}$/.test(provided))return res.status(401).json({message:'بيانات المراقبة غير مصرح بها.'});
  const scope=await networkScope(String(req.params.slug));
  const accepted=await withNetwork(scope,async app=>{
   await app.beginTransaction();try{
    const [rows]:any=await app.query('SELECT c.configuration_snapshot FROM nas_ovpn_connections c JOIN lord_nas l ON l.id=c.nas_id WHERE c.nas_id=? AND l.archived_at IS NULL FOR UPDATE',[id]);if(!rows[0])throw new Error('NAS_NOT_FOUND');
    const config=typeof rows[0].configuration_snapshot==='string'?JSON.parse(rows[0].configuration_snapshot):rows[0].configuration_snapshot,encrypted=config?.telemetryTokenEncrypted;if(typeof encrypted!=='string')throw new Error('NAS_TELEMETRY_UNAVAILABLE');
    const expected=Buffer.from(decryptProvisioningSecret(encrypted)),actual=Buffer.from(provided);if(expected.length!==actual.length||!timingSafeEqual(expected,actual))throw new Error('NAS_TELEMETRY_AUTH');
    const numeric=(key:string,min:number,max:number)=>{const value=Number(req.body?.[key]);if(!Number.isFinite(value)||value<min||value>max)throw new Error('NAS_TELEMETRY_INPUT');return value;};
    const now=Date.now(),samples=Array.isArray(config.telemetrySamples)?config.telemetrySamples:[],last=samples[samples.length-1];if(last?.receivedAt&&now-new Date(last.receivedAt).getTime()<30000)return false;
    const freeMemory=numeric('freeMemory',0,Number.MAX_SAFE_INTEGER),totalMemory=numeric('totalMemory',1,Number.MAX_SAFE_INTEGER);if(freeMemory>totalMemory)throw new Error('NAS_TELEMETRY_INPUT');
    const temperature=req.body?.temperature===null||req.body?.temperature===''?null:numeric('temperature',-30,150),sample={receivedAt:new Date(now).toISOString(),cpu:numeric('cpu',0,100),freeMemory,totalMemory,temperature,version:String(req.body?.version||'').slice(0,40),board:String(req.body?.board||'').slice(0,100),uptime:String(req.body?.uptime||'').slice(0,40)};
    config.telemetrySamples=[...samples,sample].slice(-36);config.telemetryLatest=sample;
    await app.query('UPDATE nas_ovpn_connections SET configuration_snapshot=? WHERE nas_id=?',[JSON.stringify(config),id]);if(sample.version)await app.query('UPDATE lord_nas SET routeros_version=? WHERE id=?',[sample.version,id]);
    await app.commit();return true;
   }catch(error){await app.rollback();throw error;}
  });
  if(!accepted)return res.status(429).json({message:'وصلت قراءة حديثة بالفعل.'});return res.status(204).end();
 }catch(e){const code=(e as Error).message;return res.status(code==='NAS_TELEMETRY_AUTH'||code==='NAS_TELEMETRY_UNAVAILABLE'?401:code==='NETWORK_NOT_AVAILABLE'?404:code==='NAS_TELEMETRY_INPUT'?422:code==='NAS_NOT_FOUND'?404:503).json({message:code==='NAS_TELEMETRY_INPUT'?'بيانات موارد الجهاز غير صالحة.':'تعذر حفظ قراءة NAS.'});}
});
router.get('/:slug/nas/:id/script',async(req,res)=>{let central:any,locked=false;try{const scope=await principal(req),id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)throw new Error('NAS_INPUT_INVALID');central=await db.pool.getConnection();const [lock]:any=await central.query("SELECT GET_LOCK('radius-lord:database-provisioner',0) acquired");if(!lock[0]?.acquired)throw new Error('NAS_PROVISIONING_BUSY');locked=true;const script=await withNetwork(scope,async app=>{const snapshot=await readNetworkOvpn(app);if(!snapshot)throw new Error('NAS_NEW_ENVIRONMENT_REQUIRED');await setManagedNasRadiusSecret(app,id);await syncNasRadius(central,app,scope,snapshot);return networkNasScript(central,app,id,scope);});res.setHeader('Cache-Control','no-store, private');res.setHeader('Pragma','no-cache');res.setHeader('Content-Type','text/plain; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="radius-lord-nas-${id}.rsc"`);return res.send(script);}catch(e){return res.status(409).json(nasError(e));}finally{if(locked&&central)await central.query("SELECT RELEASE_LOCK('radius-lord:database-provisioner')");central?.release();}});
router.post('/:slug/nas/:id/api-check',async(req,res)=>{let central:any;try{const scope=await principal(req),id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)throw new Error('NAS_INPUT_INVALID');central=await db.pool.getConnection();const result=await withNetwork(scope,app=>checkNetworkNasApi(central,app,id,scope));if(!result.connection)throw new Error('NAS_API_INVALID_RESPONSE');const connection=result.connection;return res.json({success:true,...result,message:connection.transport==='direct'?`نجح API عبر المسار المباشر · المصدر ${connection.sourceAddress} · NAS ${connection.targetAddress}:${result.apiPort} · ${connection.elapsedMs} ms`:`نجح API عبر بوابة OVPN · المصدر ${connection.sourceAddress} · البوابة ${connection.targetAddress}:${connection.relayPort} · ${connection.elapsedMs} ms`});}catch(e){const code=(e as Error).message,diagnostics=(e as Error&{diagnostics?:unknown}).diagnostics;const known:Record<string,string>={NAS_API_NOT_CONFIGURED:'إعداد API أو بيانات الدخول غير موجودة لهذا الجهاز.',NAS_API_DISABLED:'خدمة API أو جهاز NAS متوقف.',NAS_API_PORT_INVALID:'منفذ API المحفوظ غير صالح.',NAS_API_EMPTY_RESPONSE:'اتصل API لكن لم يُرجع بيانات موارد.',NAS_API_INVALID_RESPONSE:'استجابة API لا تحتوي قيماً صالحة لموارد الجهاز.',NAS_API_ROUTE_UNAVAILABLE:'تعذر على خادم التطبيق الوصول إلى واجهة إدارة بوابة OVPN.',NAS_API_TCP_TIMEOUT:'انتهت مهلة الاتصال ببوابة OVPN أو بمسار API عبر النفق؛ تحقق من الاتصال والجدار الناري.',NAS_API_TCP_REFUSED:'رفضت بوابة OVPN الاتصال بمنفذ API؛ تحقق من منفذ الإدارة المحفوظ.',NAS_API_TCP_FAILED:'فشل اتصال TCP بين التطبيق وبوابة OVPN أو بين البوابة وNAS.',NAS_API_LOGIN_FAILED:'وصل الفحص إلى NAS عبر نفق OVPN، لكن MikroTik رفض بيانات API أو صلاحياتها.',NAS_OVPN_TUNNEL_NOT_CONNECTED:'بوابة OVPN لا ترى نفق هذا الجهاز متصلاً حاليًا.',NAS_API_RELAY_PORT_UNAVAILABLE:'تعذر اختيار منفذ مؤقت لفحص API على بوابة OVPN.'};const message=known[code]??(code==='NETWORK_AUTH'?'انتهت الجلسة أو لا تملك صلاحية إدارة الخوادم.':code==='NAS_NOT_FOUND'?'جهاز NAS غير موجود.':code==='فشل تسجيل الدخول إلى API. تحقق من بيانات الدخول والصلاحيات.'?'وصل الاتصال لكن رفض MikroTik بيانات الدخول أو صلاحيات المستخدم.':'فشل فحص API عبر بوابة OVPN؛ تحقق من إعدادات البوابة والنفق ثم أعد المحاولة.');return res.status(code==='NETWORK_AUTH'?401:code==='NAS_NOT_FOUND'?404:502).json({success:false,apiCode:/^[A-Z0-9_]+$/.test(code)?code:'API_CONNECTION_FAILED',message,diagnostics});}finally{central?.release();}});
async function provisionNasRequest(req:Request,res:any,refresh=false){
 const central=await db.pool.getConnection();let locked=false,provisionedNasId:number|undefined;
 try{const [lock]:any=await central.query("SELECT GET_LOCK('radius-lord:database-provisioner',0) acquired");if(!lock[0]?.acquired)throw new Error('NAS_PROVISIONING_BUSY');locked=true;
 const scope=await principal(req);
 await withNetwork(scope,async app=>{
 const snapshot=await readNetworkOvpn(app);if(!snapshot)throw new Error('NAS_NEW_ENVIRONMENT_REQUIRED');const license=await validateLocalLicense(app,scope);if(snapshot.maxNas!==Number(license.base_max_nas)||snapshot.additionalNas!==Number(license.additional_nas_capacity))throw new Error('NAS_LICENSE_SNAPSHOT_CHANGED');
 if(refresh){await refreshNasLinks(central,app,scope,snapshot);return;}
 const id=req.params.id?Number(req.params.id):await createNetworkNas(app,scope,scope.managerId,snapshot,{name:String(req.body?.name??''),requestId:String(req.body?.requestId??''),vendor:String(req.body?.vendor??'mikrotik'),model:String(req.body?.model??''),radiusServices:Array.isArray(req.body?.radiusServices)?req.body.radiusServices:undefined,location:String(req.body?.location??''),description:String(req.body?.description??''),enabled:req.body?.enabled,apiPort:Number(req.body?.apiPort??8728)});if(!Number.isSafeInteger(id)||id<1)throw new Error('NAS_INPUT_INVALID');provisionedNasId=id;
 await provisionNetworkNas(central,app,scope,id,snapshot);
 await setManagedNasRadiusSecret(app,id);
 await syncNasRadius(central,app,scope,snapshot);
 });return res.json({success:true,...(provisionedNasId?{nasId:provisionedNasId}:{}),message:refresh?'تم تحديث حالة الأنفاق من البوابة.':'تم إنشاء NAS وربطه بخدمة RADIUS.'});
 }catch(e){return res.status(409).json(nasError(e));}finally{if(locked)await central.query("SELECT RELEASE_LOCK('radius-lord:database-provisioner')");central.release();}
}
router.post('/:slug/nas',async(req,res)=>provisionNasRequest(req,res));
router.post('/:slug/nas/:id/retry',async(req,res)=>provisionNasRequest(req,res));
router.put('/:slug/nas/:id',async(req,res)=>{
 try{const id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)throw new Error('NAS_INPUT_INVALID');const scope=await principal(req);const result=await withNetwork(scope,app=>updateNetworkNasDetails(app,id,req.body||{}));return res.json({success:true,message:'تم تحديث بيانات NAS.',nas:result});}
 catch(e){const code=(e as Error).message;return res.status(code==='NETWORK_AUTH'?401:code==='NAS_NOT_FOUND'?404:code==='NAS_DETAILS_INPUT'||code==='NAS_INPUT_INVALID'?422:409).json(nasError(e));}
});
router.post('/:slug/nas/:id/status',async(req,res)=>{
 const central=await db.pool.getConnection();let locked=false;
 try{
  const id=Number(req.params.id),enabled=req.body?.enabled;if(!Number.isSafeInteger(id)||id<1||typeof enabled!=='boolean')throw new Error('NAS_STATUS_INPUT');
  const [lock]:any=await central.query("SELECT GET_LOCK('radius-lord:database-provisioner',0) acquired");if(!lock[0]?.acquired)throw new Error('NAS_PROVISIONING_BUSY');locked=true;
  const scope=await principal(req);
  await withNetwork(scope,async app=>{
   const snapshot=await readNetworkOvpn(app);if(!snapshot)throw new Error('NAS_NEW_ENVIRONMENT_REQUIRED');
   const license=await validateLocalLicense(app,scope);if(snapshot.maxNas!==Number(license.base_max_nas)||snapshot.additionalNas!==Number(license.additional_nas_capacity))throw new Error('NAS_LICENSE_SNAPSHOT_CHANGED');
   const [rows]:any=await app.query('SELECT is_enabled FROM lord_nas WHERE id=? AND archived_at IS NULL',[id]);if(!rows[0])throw new Error('NAS_NOT_FOUND');
   const previous=Boolean(rows[0].is_enabled);if(previous===enabled)return;
   await setNetworkNasEnabled(app,id,enabled);
   try{await syncNasRadius(central,app,scope,snapshot);}catch(error){await setNetworkNasEnabled(app,id,previous);throw error;}
  });
  return res.json({success:true,enabled,message:enabled?'تم تفعيل NAS وتحديث عملاء RADIUS.':'تم إيقاف NAS وإزالته من عملاء RADIUS.'});
 }catch(e){return res.status((e as Error).message==='NETWORK_AUTH'?401:409).json(nasError(e));}
 finally{if(locked)await central.query("SELECT RELEASE_LOCK('radius-lord:database-provisioner')");central.release();}
});
router.post('/:slug/nas-check',async(req,res)=>provisionNasRequest(req,res,true));
router.post('/:slug/activate',async(req,res)=>{
 const key='activate:'+(req.ip??'');const now=Date.now(),attempts=failed.get(key);if(attempts&&attempts.until>now&&attempts.count>=10)return res.status(429).json({message:'انتظر دقائق قبل إعادة المحاولة.'});
 try{const username=await consumeActivation(String(req.params.slug),String(req.body?.token??''),String(req.body?.password??''));failed.delete(key);return res.json({success:true,username,message:'تم تعيين كلمة المرور. يمكنك تسجيل الدخول الآن.'});}
 catch{for(const [k,v]of Array.from(failed))if(v.until<=now)failed.delete(k);if(failed.size>1000)failed.clear();failed.set(key,{count:attempts&&attempts.until>now?attempts.count+1:1,until:now+300000});return res.status(400).json({message:'الرابط غير صالح أو انتهت صلاحيته أو استُخدم. كلمة المرور يجب أن تكون من 8 إلى 128 محرفًا.'});}
});
router.post('/:slug/login',async(req,res)=>{
 let loginScope:any=null;
 const key=req.ip??'';const now=Date.now();const attempts=failed.get(key);if(attempts&&attempts.until>now&&attempts.count>=10)return res.status(429).json({message:'انتظر دقائق قبل إعادة المحاولة.'});
 try{
  const username=String(req.body?.username??''),password=String(req.body?.password??'');if(username.length>100||password.length>128||!username||!password)throw new Error('INVALID_LOGIN');
  const scope=await networkScope(String(req.params.slug));loginScope=scope;const manager=await withNetwork(scope,async connection=>{await validateLocalLicense(connection,scope);const [rows]:any=await connection.query("SELECT id,full_name,password_hash FROM managers WHERE username=? AND is_enabled=1 AND archived_at IS NULL AND (manager_type='principal' OR EXISTS(SELECT 1 FROM permission_groups g WHERE g.id=managers.permission_group_id AND g.is_enabled=1 AND g.archived_at IS NULL))",[username]);if(rows[0])await managerAccess(connection,Number(rows[0].id));if(!rows[0]||!await bcrypt.compare(password,rows[0].password_hash))throw new Error('INVALID_LOGIN');return rows[0];});
  const runtime=await readPrivateSetting('environment_runtime','environment_'+scope.environment_id);
  if(runtime?.mustChangeCredentials===true&&username!==runtime.pendingUsername&&(!runtime.credentialsExpiresAt||new Date(runtime.credentialsExpiresAt).getTime()<=Date.now()))throw new Error('CREDENTIALS_EXPIRED');
  failed.delete(key);const sessionVersion=await networkSessionVersion(scope,Number(manager.id));const token=jwt.sign({sessionVersion,kind:'network-manager',tenantId:scope.tenant_id,environmentId:scope.environment_id,authVersion:createHash('sha256').update(manager.password_hash).digest('hex'),sub:String(manager.id),slug:scope.slug},env.JWT_SECRET,{algorithm:'HS256',expiresIn:'20m'});
  await withNetwork(scope,app=>auditNetworkEvent(app,{action:'auth.login',managerId:Number(manager.id)}));
  res.cookie('network_token',token,{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',path:'/api/network',maxAge:1200000});return res.json({success:true,name:manager.full_name});
 }catch{if(loginScope)await auditRejectedLogin(loginScope);for(const [k,v]of Array.from(failed))if(v.until<=now)failed.delete(k);if(failed.size>1000)failed.clear();failed.set(key,{count:attempts&&attempts.until>now?attempts.count+1:1,until:now+300000});return res.status(401).json({message:'بيانات الدخول غير صحيحة أو البيئة غير متاحة.'});}
});
router.post('/:slug/credentials',async(req,res)=>{try{
 const token:any=jwt.verify(cookie(req.headers.cookie),env.JWT_SECRET,{algorithms:['HS256']});
 if(token.kind!=='network-manager'||token.slug!==req.params.slug)throw new Error('NETWORK_AUTH');
 const scope=await networkScope(String(req.params.slug));if(Number(token.tenantId)!==Number(scope.tenant_id)||Number(token.environmentId)!==Number(scope.environment_id))throw new Error('NETWORK_AUTH');
 const fresh=await changeInitialCredentials(scope,token,req.body);
 res.cookie('network_token',fresh,{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',path:'/api/network',maxAge:1200000});return res.json({success:true});
 }catch(e){const code=(e as Error).message;const messages:Record<string,string>={USERNAME_TAKEN:'اسم المستخدم مستخدم بالفعل، اختر اسمًا آخر.',CREDENTIALS_INPUT:'استخدم اسمًا إنكليزيًا من 3 إلى 64 محرفًا يبدأ بحرف، وكلمة مرور من 8 إلى 128 محرفًا.',CREDENTIALS_REUSE:'اختر اسم مستخدم وكلمة مرور مختلفين عن البيانات المؤقتة.',CREDENTIALS_EXPIRED:'انتهت صلاحية البيانات المؤقتة؛ راجع الإدارة.',CREDENTIALS_BUSY:'جارٍ حفظ بيانات حساب آخر؛ أعد المحاولة.'};return res.status(409).json({message:messages[code]||'تعذر حفظ البيانات. أعد الدخول ثم حاول مجددًا.'});}
});
router.post('/:slug/logout',async(req,res)=>{try{const token:any=jwt.verify(cookie(req.headers.cookie),env.JWT_SECRET,{algorithms:['HS256']});const scope=await networkScope(String(req.params.slug));if(token.kind==='network-manager'&&token.slug===scope.slug&&Number(token.tenantId)===Number(scope.tenant_id)&&Number(token.environmentId)===Number(scope.environment_id)&&token.sessionVersion===await networkSessionVersion(scope,Number(token.sub)))await withNetwork(scope,async app=>{await managerAccess(app,Number(token.sub),token.authVersion);await auditNetworkEvent(app,{action:'auth.logout',managerId:Number(token.sub)});});}catch{console.error('[network-audit]',{action:'auth.logout',result:'unverified_or_audit_unavailable'});}res.clearCookie('network_token',{path:'/api/network',httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production'});return res.json({success:true});});
router.get('/:slug/me',async(req,res)=>{
 try{const token:any=jwt.verify(cookie(req.headers.cookie),env.JWT_SECRET,{algorithms:['HS256']});if(token.kind!=='network-manager'||token.slug!==req.params.slug)throw new Error('SCOPE');const scope=await networkScope(String(req.params.slug));if(Number(token.tenantId)!==Number(scope.tenant_id)||Number(token.environmentId)!==Number(scope.environment_id))throw new Error('SCOPE');
 if((token.sessionVersion||'0')!==await networkSessionVersion(scope,Number(token.sub)))throw new Error('NETWORK_AUTH');
 const mustChangeCredentials=await credentialsRequired(scope);
 const result=await withNetwork(scope,async connection=>{const license=await validateLocalLicense(connection,scope);const [rows]:any=await connection.query("SELECT id,full_name,manager_type,password_hash FROM managers WHERE id=? AND is_enabled=1 AND archived_at IS NULL AND (manager_type='principal' OR EXISTS(SELECT 1 FROM permission_groups g WHERE g.id=managers.permission_group_id AND g.is_enabled=1 AND g.archived_at IS NULL))",[token.sub]);if(!rows[0]||token.authVersion!==createHash('sha256').update(rows[0].password_hash).digest('hex'))throw new Error('MANAGER');const access=await managerAccess(connection,Number(rows[0].id),token.authVersion);return {mustChangeCredentials,manager:{id:rows[0].id,full_name:rows[0].full_name,manager_type:rows[0].manager_type,account_role:access.role,permissions:access.permissions},networkName:(await connection.query<any[]>('SELECT network_name FROM network_settings WHERE id=1'))[0][0]?.network_name||scope.name,license:license.license_number,expiresAt:license.expires_at,planName:license.plan_name_snapshot,durationMonths:Number(license.duration_months_snapshot),startsAt:license.starts_at,maxSubscribers:Number(license.max_pppoe_accounts),maxNas:Number(license.base_max_nas)===0?0:Number(license.base_max_nas)+Number(license.additional_nas_capacity)};});return res.json(result);
 }catch{return res.status(401).json({message:'انتهت الجلسة أو البيئة غير متاحة.'});}
});
// Worker-only HTTP proof: this exercises the same network scope, DB and password verification as login.
router.post('/:slug/verify',async(req,res)=>{
 try{const proof:any=jwt.verify(String(req.headers['x-provisioning-proof']??''),provisioningKey(),{algorithms:['HS256']});if(proof.kind!=='network-bootstrap'||proof.slug!==req.params.slug)throw new Error('PROOF');
 const scope=await networkScope(String(req.params.slug),true);if(Number(proof.environmentId)!==Number(scope.environment_id))throw new Error('PROOF');
 const [jobs]:any=await db.query("SELECT id FROM environment_provisioning_jobs WHERE id=? AND environment_id=? AND tenant_id=? AND status='running'",[proof.jobId,scope.environment_id,scope.tenant_id]);if(!jobs[0])throw new Error('JOB');
 await withNetwork(scope,async connection=>{await validateLocalLicense(connection,scope,true);const [rows]:any=await connection.query("SELECT password_hash FROM managers WHERE username=? AND manager_type='principal' AND is_enabled=1 AND archived_at IS NULL",[String(req.body?.username??'')]);if(!rows[0]||!await bcrypt.compare(String(req.body?.password??''),rows[0].password_hash))throw new Error('LOGIN');});
 return res.json({application:'radius-lord-network',environmentId:scope.environment_id,tenantId:scope.tenant_id,nonce:proof.nonce});
 }catch{return res.status(403).json({message:'فشل التحقق من بيئة الشبكة.'});}
});
